1	/**
2	 * errors.mjs — the python-jose exception hierarchy, ported to ES classes.
3	 *
4	 * python-jose (jose/exceptions.py) defines a small tree of exceptions:
5	 *
6	 *   JOSEError
7	 *   ├── JWSError
8	 *   │   ├── JWSSignatureError
9	 *   │   └── JWSAlgorithmError
10	 *   ├── JWTError
11	 *   │   ├── JWTClaimsError
12	 *   │   └── ExpiredSignatureError
13	 *   └── JWKError
14	 *
15	 * Python exceptions carry no default message (str(JWSError()) == ''), but a
16	 * handful of raise sites in python-jose always use the same wording. Those
17	 * strings are exposed here as the static `DEFAULT_MESSAGE` of the matching
18	 * class, so `new JWSSignatureError()` reads like the library's own raise.
19	 *
20	 * This module has no imports of any kind — by design it is pure, dependency
21	 * free, and safe to load from anywhere in the port.
22	 */
23	
24	/**
25	 * Resolve the message passed to a constructor into the string that `super()`
26	 * receives.
27	 *
28	 * - `undefined` / `null` (i.e. "no message given") -> the class default,
29	 *   mirroring Python's `raise JWSError` with no arguments.
30	 * - an Error instance -> its message, mirroring python-jose's habit of
31	 *   re-raising a caught exception as `raise JWSError(e)`, where `str(e)` is
32	 *   what the user ends up seeing.
33	 * - anything else -> coerced with String(), like Python's str().
34	 *
35	 * @param {unknown} message value handed to the constructor
36	 * @param {Function} target the concrete class being constructed (new.target)
37	 * @returns {string} message for the underlying Error
38	 */
39	function normalizeMessage(message, target) {
40	  if (message === undefined || message === null) {
41	    const fallback = target && target.DEFAULT_MESSAGE;
42	    return typeof fallback === 'string' ? fallback : '';
43	  }
44	  if (message instanceof Error) {
45	    return String(message.message);
46	  }
47	  return String(message);
48	}
49	
50	/**
51	 * Base class for every error raised by this library.
52	 * Equivalent to jose.exceptions.JOSEError.
53	 */
54	export class JOSEError extends Error {
55	  /** python-jose has no default text for the base class. */
56	  static DEFAULT_MESSAGE = '';
57	
58	  /**
59	   * @param {unknown} [message] optional message (or a wrapped Error)
60	   */
61	  constructor(message) {
62	    super(normalizeMessage(message, new.target));
63	    this.name = 'JOSEError';
64	    // Keep the constructor frames out of the stack when V8 lets us.
65	    if (typeof Error.captureStackTrace === 'function') {
66	      Error.captureStackTrace(this, new.target);
67	    }
68	  }
69	}
70	
71	/**
72	 * Something went wrong while signing or verifying a JWS.
73	 * Equivalent to jose.exceptions.JWSError.
74	 */
75	export class JWSError extends JOSEError {
76	  /**
77	   * @param {unknown} [message] optional message (or a wrapped Error)
78	   */
79	  constructor(message) {
80	    super(message);
81	    this.name = 'JWSError';
82	  }
83	}
84	
85	/**
86	 * The signature did not match the signing input for any candidate key.
87	 * Equivalent to jose.exceptions.JWSSignatureError.
88	 */
89	export class JWSSignatureError extends JWSError {
90	  /** jws._verify_signature: raise JWSSignatureError("Signature verification failed.") */
91	  static DEFAULT_MESSAGE = 'Signature verification failed.';
92	
93	  /**
94	   * @param {unknown} [message] optional message (or a wrapped Error)
95	   */
96	  constructor(message) {
97	    super(message);
98	    this.name = 'JWSSignatureError';
99	  }
100	}
101	
102	/**
103	 * The requested / advertised algorithm is not implemented.
104	 * Equivalent to jose.exceptions.JWSAlgorithmError.
105	 */
106	export class JWSAlgorithmError extends JWSError {
107	  /** jws: raise JWSAlgorithmError("Algorithm not supported.") */
108	  static DEFAULT_MESSAGE = 'Algorithm not supported.';
109	
110	  /**
111	   * @param {unknown} [message] optional message (or a wrapped Error)
112	   */
113	  constructor(message) {
114	    super(message);
115	    this.name = 'JWSAlgorithmError';
116	  }
117	}
118	
119	/**
120	 * Something went wrong while encoding or decoding a JWT.
121	 * Equivalent to jose.exceptions.JWTError.
122	 */
123	export class JWTError extends JOSEError {
124	  /**
125	   * @param {unknown} [message] optional message (or a wrapped Error)
126	   */
127	  constructor(message) {
128	    super(message);
129	    this.name = 'JWTError';
130	  }
131	}
132	
133	/**
134	 * A registered claim failed validation (iat, aud, iss, sub, jti, at_hash, ...).
135	 * Equivalent to jose.exceptions.JWTClaimsError.
136	 */
137	export class JWTClaimsError extends JWTError {
138	  /**
139	   * @param {unknown} [message] optional message (or a wrapped Error)
140	   */
141	  constructor(message) {
142	    super(message);
143	    this.name = 'JWTClaimsError';
144	  }
145	}
146	
147	/**
148	 * The `exp` claim is in the past (outside the allowed leeway).
149	 * Equivalent to jose.exceptions.ExpiredSignatureError.
150	 */
151	export class ExpiredSignatureError extends JWTError {
152	  /** jwt._validate_exp: raise ExpiredSignatureError("Signature has expired.") */
153	  static DEFAULT_MESSAGE = 'Signature has expired.';
154	
155	  /**
156	   * @param {unknown} [message] optional message (or a wrapped Error)
157	   */
158	  constructor(message) {
159	    super(message);
160	    this.name = 'ExpiredSignatureError';
161	  }
162	}
163	
164	/**
165	 * A key could not be constructed or used.
166	 * Equivalent to jose.exceptions.JWKError — included for hierarchy fidelity;
167	 * the HS256-only port raises it only when a key is unusable.
168	 */
169	export class JWKError extends JOSEError {
170	  /**
171	   * @param {unknown} [message] optional message (or a wrapped Error)
172	   */
173	  constructor(message) {
174	    super(message);
175	    this.name = 'JWKError';
176	  }
177	}
