1	/**
2	 * pyjson.mjs — a byte-faithful reimplementation of the two CPython `json`
3	 * entry points this port needs:
4	 *
5	 *   pyJsonDumpsCompact(value)  ==  json.dumps(value, separators=(',', ':'))
6	 *                                  with the default ensure_ascii=True
7	 *   pyJsonLoads(text)          ==  json.loads(text)
8	 *
9	 * Why hand-written instead of JSON.stringify / JSON.parse:
10	 *
11	 * 1. `JSON.stringify` leaves every printable non-ASCII character raw, while
12	 *    CPython escapes anything outside 0x20..0x7e (so U+4E2D becomes 中 and
13	 *    U+007F becomes ). The JWT payload must match the reference bytes
14	 *    exactly, because the signature is computed over them.
15	 * 2. `JSON.parse` returns plain objects, which silently reorder integer-like
16	 *    keys ({"2":1,"1":2} comes back as {1:2, 2:1}). Python dicts preserve
17	 *    insertion order and the decoded-claims line printed by the program is a
18	 *    dict repr, so order is observable. Objects are therefore returned as
19	 *    `Map` instances.
20	 * 3. Python distinguishes `int` from `float`: repr(1) is "1" but repr(1.0) is
21	 *    "1.0". JSON.parse collapses both into one Number. See "Float tagging".
22	 *
23	 * ── Float tagging ────────────────────────────────────────────────────────────
24	 * `isJsonInteger(value)` is the discriminator pyrepr.mjs uses to pick between
25	 * Python int and Python float formatting. The rules are:
26	 *
27	 *   - A plain Number that is an integer value (Number.isInteger) counts as a
28	 *     Python int, and so does a BigInt.
29	 *   - A plain Number with a fractional part, NaN or ±Infinity is already
30	 *     unambiguously a Python float, so it needs no extra bookkeeping.
31	 *   - The only ambiguous case is a JSON *float literal whose value happens to
32	 *     be integral* — "1.0", "2e3", "-0.0". Those, and only those, are returned
33	 *     wrapped in the exported `PyFloat` marker class, whose `isJsonInteger` is
34	 *     false and whose `toString()` already yields the Python repr ("1.0").
35	 *
36	 * Wrapping is kept to that minimum on purpose: every other value stays a
37	 * primitive Number, so consumers that only understand primitives keep working.
38	 * `PyFloat` defines `valueOf()`, so arithmetic and comparisons still behave.
39	 * (The payloads this program handles — a string plus an integer `iat` — never
40	 * contain a float at all, so in practice no marker is ever produced.)
41	 *
42	 * Integers are returned as Numbers per the module contract. A JSON integer
43	 * larger than 2**53-1 therefore loses precision, exactly where Python would
44	 * have kept an arbitrary-precision int; the serialiser, however, still writes
45	 * large integral Numbers back out as exact digits (never "1e+21").
46	 */
47	
48	import { utf8Decode } from './bytes.mjs';
49	
50	/** Characters CPython's json module treats as whitespace between tokens. */
51	const WHITESPACE = ' \t\n\r';
52	
53	/** Escapes CPython emits for these code points instead of a \uXXXX form. */
54	const SHORT_ESCAPES = new Map([
55	  [0x08, '\\b'],
56	  [0x09, '\\t'],
57	  [0x0a, '\\n'],
58	  [0x0c, '\\f'],
59	  [0x0d, '\\r'],
60	]);
61	
62	/** Reverse table for the one-character escapes accepted by the parser. */
63	const SIMPLE_UNESCAPES = new Map([
64	  ['"', '"'],
65	  ['\\', '\\'],
66	  ['/', '/'],
67	  ['b', '\b'],
68	  ['f', '\f'],
69	  ['n', '\n'],
70	  ['r', '\r'],
71	  ['t', '\t'],
72	]);
73	
74	/** JSON number grammar, anchored so it can be applied at an offset. */
75	const NUMBER_PATTERN = /-?(?:0|[1-9][0-9]*)(\.[0-9]+)?([eE][-+]?[0-9]+)?/y;
76	
77	/** Exactly four hex digits, for \uXXXX escapes. */
78	const HEX4_PATTERN = /^[0-9a-fA-F]{4}$/;
79	
80	/**
81	 * CPython switches float repr to scientific notation when the decimal point
82	 * position is <= -4 or > 16. Expressed against the exponent of the normalised
83	 * mantissa (value = d.ddd * 10**exp) that is exp <= -5 or exp > 15.
84	 */
85	const FLOAT_EXP_LOW = -5;
86	const FLOAT_EXP_HIGH = 15;
87	
88	/**
89	 * Marker for a Python float whose value happens to be integral ("1.0", "2e3").
90	 *
91	 * Only the parser creates these, and only for that ambiguous case; see the
92	 * "Float tagging" note at the top of the file.
93	 */
94	export class PyFloat {
95	  /**
96	   * @param {number} value the numeric value (must be finite and integral to be
97	   *   worth marking, though any number is accepted)
98	   */
99	  constructor(value) {
100	    /** @type {number} */
101	    this.value = Number(value);
102	    // Tag fields, so a consumer that does not import PyFloat (pyrepr.mjs looks
103	    // for exactly these shapes) still recognises the wrapper as a float rather
104	    // than walking it as a dict.
105	    /** @type {true} */
106	    this.__pyFloat = true;
107	    /** @type {'float'} */
108	    this.pyType = 'float';
109	    /** @type {true} */
110	    this.isFloat = true;
111	  }
112	
113	  /** Let arithmetic, comparisons and Number() see through the wrapper. */
114	  valueOf() {
115	    return this.value;
116	  }
117	
118	  /** String coercion yields the Python float repr, e.g. "1.0" / "-0.0". */
119	  toString() {
120	    return pythonFloatRepr(this.value);
121	  }
122	
123	  /** Keep the wrapper transparent to the builtin JSON serialiser too. */
124	  toJSON() {
125	    return this.value;
126	  }
127	}
128	
129	/**
130	 * Python's json.JSONDecodeError: a ValueError carrying the failure position.
131	 * The `message` is formatted exactly like CPython's, e.g.
132	 * "Expecting value: line 1 column 1 (char 0)".
133	 */
134	export class JSONDecodeError extends Error {
135	  /**
136	   * @param {string} msg the bare reason, without position information
137	   * @param {string} doc the document being parsed
138	   * @param {number} pos zero-based offset of the offending character
139	   */
140	  constructor(msg, doc, pos) {
141	    const lineno = countNewlines(doc, pos) + 1;
142	    const colno = pos - doc.lastIndexOf('\n', pos - 1);
143	    super(`${msg}: line ${lineno} column ${colno} (char ${pos})`);
144	    this.name = 'JSONDecodeError';
145	    /** @type {string} the reason without position, like CPython's `.msg` */
146	    this.msg = msg;
147	    /** @type {string} */
148	    this.doc = doc;
149	    /** @type {number} */
150	    this.pos = pos;
151	    /** @type {number} */
152	    this.lineno = lineno;
153	    /** @type {number} */
154	    this.colno = colno;
155	  }
156	}
157	
158	/**
159	 * Serialise a value the way `json.dumps(value, separators=(',', ':'))` does:
160	 * no whitespace after ':' or ',', and ensure_ascii=True so every code unit
161	 * outside 0x20..0x7e is escaped.
162	 *
163	 * Accepted inputs: Map (preferred — preserves key order), plain object, Array,
164	 * string, number, BigInt, PyFloat, boolean, null and undefined (like None).
165	 *
166	 * @param {*} value the value to serialise
167	 * @returns {string} the compact JSON text
168	 * @throws {TypeError} for a value (or dict key) Python could not serialise
169	 * @throws {Error} when the value graph contains a cycle
170	 */
171	export function pyJsonDumpsCompact(value) {
172	  return serialise(value, new Set());
173	}
174	
175	/**
176	 * Parse JSON text into Python-shaped values.
177	 *
178	 * Mapping: object -> Map (insertion ordered), array -> Array, string -> string,
179	 * integer literal -> Number, float literal -> Number or PyFloat (see the
180	 * "Float tagging" note), true/false -> boolean, null -> null. The non-standard
181	 * constants CPython accepts by default — NaN, Infinity, -Infinity — are
182	 * accepted too and yield the matching JS numbers.
183	 *
184	 * @param {string|Uint8Array|number[]} text JSON document; byte input is decoded
185	 *   as UTF-8 first, matching json.loads(bytes)
186	 * @returns {*} the parsed value
187	 * @throws {JSONDecodeError} on malformed input, with CPython's message
188	 * @throws {TypeError} when `text` is not text or bytes
189	 */
190	export function pyJsonLoads(text) {
191	  const doc = coerceDocument(text);
192	
193	  // CPython rejects a byte-order mark up front rather than at the value scan.
194	  if (doc.charCodeAt(0) === 0xfeff) {
195	    throw new JSONDecodeError('Unexpected UTF-8 BOM (decode using utf-8-sig)', doc, 0);
196	  }
197	
198	  const state = { doc, pos: 0 };
199	  skipWhitespace(state);
200	  const value = parseValue(state);
201	  skipWhitespace(state);
202	
203	  if (state.pos < doc.length) {
204	    throw new JSONDecodeError('Extra data', doc, state.pos);
205	  }
206	  return value;
207	}
208	
209	/**
210	 * Would Python have called this value an `int`?
211	 *
212	 * True for integral Numbers and BigInts; false for PyFloat markers, for
213	 * fractional/NaN/Infinite Numbers, and for everything that is not a number.
214	 *
215	 * @param {*} value candidate value
216	 * @returns {boolean} true when the value should be repr'd as a Python int
217	 */
218	export function isJsonInteger(value) {
219	  if (typeof value === 'bigint') {
220	    return true;
221	  }
222	  if (value instanceof PyFloat) {
223	    return false;
224	  }
225	  return typeof value === 'number' && Number.isInteger(value);
226	}
227	
228	/**
229	 * Complement of {@link isJsonInteger} restricted to numeric values: true for
230	 * PyFloat markers and for Numbers Python would print with a decimal point or
231	 * as inf/nan.
232	 *
233	 * @param {*} value candidate value
234	 * @returns {boolean} true when the value should be repr'd as a Python float
235	 */
236	export function isJsonFloat(value) {
237	  if (value instanceof PyFloat) {
238	    return true;
239	  }
240	  return typeof value === 'number' && !Number.isInteger(value);
241	}
242	
243	/**
244	 * Unwrap a PyFloat marker (or pass a plain number through), so callers never
245	 * have to special-case the marker when they only want the numeric value.
246	 *
247	 * @param {*} value number, BigInt or PyFloat
248	 * @returns {number} the numeric value
249	 */
250	export function jsonNumberValue(value) {
251	  if (value instanceof PyFloat) {
252	    return value.value;
253	  }
254	  if (typeof value === 'bigint') {
255	    return Number(value);
256	  }
257	  return Number(value);
258	}
259	
260	/**
261	 * Format a JS number the way `repr()` formats a Python float: shortest
262	 * round-tripping digits, always a decimal point or an exponent, exponents
263	 * signed and zero-padded to at least two digits ("1e-07", "1e+16").
264	 *
265	 * @param {number} value the float to render
266	 * @returns {string} the Python-style repr
267	 */
268	export function pythonFloatRepr(value) {
269	  const number = Number(value);
270	
271	  if (Number.isNaN(number)) {
272	    return 'nan';
273	  }
274	  if (number === Infinity) {
275	    return 'inf';
276	  }
277	  if (number === -Infinity) {
278	    return '-inf';
279	  }
280	
281	  // Object.is catches -0, whose toExponential() drops the sign.
282	  const negative = number < 0 || Object.is(number, -0);
283	  const magnitude = negative ? -number : number;
284	
285	  // toExponential() with no argument gives the shortest digit string that
286	  // uniquely identifies the double — the same digits CPython's repr uses.
287	  const scientific = magnitude.toExponential();
288	  const eIndex = scientific.indexOf('e');
289	  const digits = scientific.slice(0, eIndex).replace('.', '');
290	  const exponent = Number(scientific.slice(eIndex + 1));
291	
292	  const body =
293	    exponent <= FLOAT_EXP_LOW || exponent > FLOAT_EXP_HIGH
294	      ? formatFloatScientific(digits, exponent)
295	      : formatFloatPositional(digits, exponent);
296	
297	  return negative ? `-${body}` : body;
298	}
299	
300	/* ────────────────────────────── serialiser ────────────────────────────── */
301	
302	/**
303	 * Recursive worker behind {@link pyJsonDumpsCompact}.
304	 *
305	 * @param {*} value value to serialise
306	 * @param {Set<object>} active containers currently on the recursion stack,
307	 *   used for CPython's check_circular behaviour
308	 * @returns {string} JSON text for `value`
309	 */
310	function serialise(value, active) {
311	  if (value === null || value === undefined) {
312	    return 'null'; // Python None
313	  }
314	  if (typeof value === 'boolean') {
315	    return value ? 'true' : 'false';
316	  }
317	  if (typeof value === 'string') {
318	    return encodeJsonStringAscii(value);
319	  }
320	  if (typeof value === 'number') {
321	    return serialiseNumber(value);
322	  }
323	  if (typeof value === 'bigint') {
324	    return value.toString(); // arbitrary-precision Python int
325	  }
326	  if (value instanceof PyFloat) {
327	    return serialiseFloat(value.value);
328	  }
329	  if (Array.isArray(value)) {
330	    return serialiseArray(value, active);
331	  }
332	  if (value instanceof Map) {
333	    return serialiseMap(value, active);
334	  }
335	  if (isPlainObject(value)) {
336	    return serialisePlainObject(value, active);
337	  }
338	
339	  throw new TypeError(`Object of type ${typeNameOf(value)} is not JSON serializable`);
340	}
341	
342	/**
343	 * Serialise a Number. Integral values are written as exact integer digits (so
344	 * a large integral Number never degrades to "1e+21", which is not valid JSON);
345	 * everything else goes through the Python float formatter.
346	 *
347	 * @param {number} value the number to write
348	 * @returns {string} JSON number text
349	 */
350	function serialiseNumber(value) {
351	  if (Number.isInteger(value)) {
352	    if (Number.isSafeInteger(value)) {
353	      return String(value); // covers -0 -> "0", like Python's int repr
354	    }
355	    // Integral but beyond 2**53-1: BigInt renders the exact stored value.
356	    return BigInt(value).toString();
357	  }
358	  return serialiseFloat(value);
359	}
360	
361	/**
362	 * Serialise a Python float, including the non-standard constants json.dumps
363	 * emits with its default allow_nan=True.
364	 *
365	 * @param {number} value the float to write
366	 * @returns {string} JSON (or JSON5-ish, for the constants) number text
367	 */
368	function serialiseFloat(value) {
369	  if (Number.isNaN(value)) {
370	    return 'NaN';
371	  }
372	  if (value === Infinity) {
373	    return 'Infinity';
374	  }
375	  if (value === -Infinity) {
376	    return '-Infinity';
377	  }
378	  return pythonFloatRepr(value);
379	}
380	
381	/**
382	 * Serialise a list with the compact separator.
383	 *
384	 * @param {Array<*>} list the array to write
385	 * @param {Set<object>} active recursion guard
386	 * @returns {string} JSON array text
387	 */
388	function serialiseArray(list, active) {
389	  guardCycle(list, active);
390	  const parts = [];
391	  for (const item of list) {
392	    parts.push(serialise(item, active));
393	  }
394	  active.delete(list);
395	  return `[${parts.join(',')}]`;
396	}
397	
398	/**
399	 * Serialise a Map as a JSON object, preserving insertion order.
400	 *
401	 * @param {Map<*, *>} map the map to write
402	 * @param {Set<object>} active recursion guard
403	 * @returns {string} JSON object text
404	 */
405	function serialiseMap(map, active) {
406	  guardCycle(map, active);
407	  const parts = [];
408	  for (const [key, item] of map) {
