85	  const outerInput = new Uint8Array(SHA256_BLOCK_SIZE + SHA256_DIGEST_SIZE);
86	  for (let i = 0; i < SHA256_BLOCK_SIZE; i += 1) {
87	    outerInput[i] = key[i] ^ OPAD_BYTE;
