107	  if (!(a instanceof Uint8Array) || !(b instanceof Uint8Array)) {
108	    return false;
109	  }
110	  if (a.length !== b.length) {
111	    return false;
112	  }
113	  let diff = 0;
114	  for (let i = 0; i < a.length; i += 1) {
115	    diff |= a[i] ^ b[i];
116	  }
117	  return diff === 0;
118	}
