/**
 * jws.mjs — compact JWS serialisation (RFC 7515), a faithful port of
 * python-jose's `jose/jws.py` restricted to the one algorithm this program
 * needs: HS256.
 *
 * A compact JWS is three base64url segments joined by dots:
 *
 *     base64url(headerJSON) "." base64url(payload) "." base64url(signature)
 *
 * and the signature is computed over the ASCII bytes of the first two segments
 * (including the dot between them) — the "signing input".
 *
 * Everything below is built on this port's own primitives: the from-scratch
 * SHA-256/HMAC in ./hmac.mjs, the hand-written base64url codec in
 * ./base64url.mjs, the hand-written UTF-8 codec in ./bytes.mjs and the
 * CPython-compatible JSON codec in ./pyjson.mjs. No platform helpers, no
 * builtin modules, no external packages.
 *
 * JWS 紧凑序列化：对应原脚本中 jose.jwt 内部调用的 jose.jws。
 */

import { JWSError, JWSSignatureError, JWSAlgorithmError, JWKError } from './errors.mjs';
import { base64UrlEncode, base64UrlDecode } from './base64url.mjs';
import { utf8Encode } from './bytes.mjs';
import { hmacSha256, constantTimeEqual } from './hmac.mjs';
import { pyJsonDumpsCompact, pyJsonLoads } from './pyjson.mjs';

/** The only algorithm this port implements. */
export const HS256 = 'HS256';

/** Algorithms `sign()`/`verify()` will actually process. */
export const SUPPORTED_ALGORITHMS = Object.freeze([HS256]);

/**
 * Marker strings python-jose refuses to accept as an HMAC secret, because a
 * caller passing one of them has almost certainly confused a public key with a
 * shared secret (jose/backends/native.py).
 */
const ASYMMETRIC_KEY_MARKERS = Object.freeze([
  '-----BEGIN PUBLIC KEY-----',
  '-----BEGIN RSA PUBLIC KEY-----',
  '-----BEGIN CERTIFICATE-----',
  'ssh-rsa',
]);

/**
 * Sign a payload and return the compact serialisation.
 *
 * The header is always `{"alg":<algorithm>,"typ":"JWT"}` — the same bytes
 * python-jose produces, which builds `{"typ": "JWT", "alg": algorithm}` and
 * then dumps it with `sort_keys=True`. Extra headers are merged in and the
 * whole mapping is re-sorted by key, so the output stays byte-identical to the
 * reference for every header shape.
 *
 * @param {Map<string, *>|object|Uint8Array|string} payload claims mapping
 *   (serialised as compact JSON) or an already-encoded payload
 * @param {string|Uint8Array|Map<string, *>|object} key shared secret, or an
 *   `oct` JWK mapping
 * @param {{headers?: (Map<string, *>|object|null), algorithm?: string}} [options]
 * @returns {string} the compact JWS `header.payload.signature`
 * @throws {JWSAlgorithmError} when `algorithm` is not HS256
 * @throws {JWSError} when the payload cannot be encoded
 */
export function sign(payload, key, { headers = null, algorithm = HS256 } = {}) {
  if (!SUPPORTED_ALGORITHMS.includes(algorithm)) {
    throw new JWSAlgorithmError('Algorithm not supported.');
  }

  const encodedHeader = encodeHeader(algorithm, headers);
  const encodedPayload = encodePayload(payload);

  // 签名输入：header 与 payload 两段用 "." 连接后的 ASCII 字节。
  const signingInput = `${encodedHeader}.${encodedPayload}`;
  const signature = hmacSha256(prepareKey(key, algorithm), utf8Encode(signingInput));

  return `${signingInput}.${base64UrlEncode(signature)}`;
