}

/**
 * Does `haystack` contain the UTF-8 bytes of `needleText`?
 *
 * @param {Uint8Array} haystack bytes to search
 * @param {string} needleText ASCII text to look for
 * @returns {boolean} true when the bytes occur somewhere in `haystack`
 */
function bytesContainAscii(haystack, needleText) {
  const needle = utf8Encode(needleText);
  if (needle.length === 0 || needle.length > haystack.length) {
    return needle.length === 0;
  }

  const limit = haystack.length - needle.length;
  for (let start = 0; start <= limit; start += 1) {
    if (matchesAt(haystack, needle, start)) {
      return true;
    }
  }
  return false;
}

/**
 * Does `needle` occur in `haystack` exactly at `start`?
 *
 * @param {Uint8Array} haystack bytes to search
 * @param {Uint8Array} needle bytes to find
 * @param {number} start offset to test
 * @returns {boolean} true on a full match
 */
function matchesAt(haystack, needle, start) {
  for (let i = 0; i < needle.length; i += 1) {
    if (haystack[start + i] !== needle[i]) {
      return false;
    }
  }
  return true;
}

/**
 * jwt.mjs — JSON Web Token encode/decode, a port of python-jose's `jose/jwt.py`
 * restricted to HS256.
 *
 * `encode()` is a thin wrapper over ./jws.mjs; `decode()` verifies the
 * signature, parses the claims and then runs the registered-claim validators,
 * each of which can be switched off through the `options` mapping — exactly the
 * knob the original script uses:
 *
 *     options = {"verify_iat": verify_iat}
 *     decoded = jwt.decode(token, secret, options=options, algorithms=["HS256"])
 *
 * Claims are returned as a `Map`, so their declaration order survives and the
 * dict repr printed by the program matches CPython byte for byte.
 *
 * JWT 编解码：对应原脚本的 jwt.encode / jwt.decode。
 */

import { JWTError, JWTClaimsError, ExpiredSignatureError, JWSError } from './errors.mjs';
import { sign as jwsSign, verify as jwsVerify, getUnverifiedHeader, HS256 } from './jws.mjs';
import { pyJsonLoads, PyFloat } from './pyjson.mjs';
import { pyInt, nowEpochSeconds } from './pytime.mjs';
import { base64UrlEncode } from './base64url.mjs';
import { sha256 } from './sha256.mjs';
import { utf8Encode } from './bytes.mjs';

/**
 * The `options` defaults of python-jose's `jwt.decode`.
 *
 * Every `verify_*` flag is on and every `require_*` flag is off, so a claim
 * that is present is checked and a claim that is absent is simply skipped.
 * Setting `require_<claim>: true` makes the claim mandatory *and* forces its
 * `verify_<claim>` flag on, mirroring `_validate_claims`.
 */
export const DEFAULT_OPTIONS = Object.freeze({
  verify_signature: true,
  verify_aud: true,
  verify_iat: true,
  verify_exp: true,
  verify_nbf: true,
  verify_iss: true,
  verify_sub: true,
  verify_jti: true,
  verify_at_hash: true,
  require_aud: false,
  require_iat: false,
  require_exp: false,
  require_nbf: false,
  require_iss: false,
  require_sub: false,
  require_jti: false,
  require_at_hash: false,
  leeway: 0,
});

/** Claims python-jose converts from a date/time value to an epoch second. */
const TIME_CLAIMS = Object.freeze(['exp', 'iat', 'nbf']);

/** Prefix of the "this claim is mandatory" option names. */
const REQUIRE_PREFIX = 'require_';

/**
 * Encode a claims mapping as a signed JWT.
 *
 * @param {Map<string, *>|object} claims the claims to sign
 * @param {string|Uint8Array|Map<string, *>|object} key the shared secret
 * @param {string} [algorithm] signing algorithm (HS256 only)
 * @param {Map<string, *>|object|null} [headers] extra protected headers
 * @param {string|null} [accessToken] when given, an `at_hash` claim is added
 * @returns {string} the compact JWS
 * @throws {JWSAlgorithmError} for an unsupported algorithm
 */
export function encode(claims, key, algorithm = HS256, headers = null, accessToken = null) {
  const working = toClaimsMap(claims);

  // python-jose turns a datetime in exp/iat/nbf into an integer epoch second;
  // the JS equivalent of that input is a Date.
  for (const name of TIME_CLAIMS) {
    const value = working.get(name);
    if (value instanceof Date) {
      working.set(name, Math.floor(value.getTime() / 1000));
    }
  }

  if (accessToken) {
    working.set('at_hash', calculateAtHash(accessToken, algorithm));
  }

  return jwsSign(working, key, { headers, algorithm });
}

/**
 * Verify and decode a JWT, returning its claims.
 *
 * @param {string|Uint8Array} token the compact JWS
 * @param {string|Uint8Array|Map<string, *>|object|Array<*>} key the shared
 *   secret, or a list of candidate secrets
 * @param {{algorithms?: (Array<string>|string|null),
 *          options?: (Map<string, *>|object|null),
 *          audience?: (string|null), issuer?: (string|Array<string>|null),
 *          subject?: (string|null), accessToken?: (string|null)}} [settings]
 * @returns {Map<string, *>} the decoded claims, in declaration order
 * @throws {JWTError} malformed token, bad signature or a missing required claim
 * @throws {JWTClaimsError} a claim failed validation
 * @throws {ExpiredSignatureError} the `exp` claim is in the past
 */
export function decode(
  token,
  key,
  { algorithms = null, options = null, audience = null, issuer = null, subject = null, accessToken = null } = {}
) {
  const mergedOptions = mergeOptions(options);
  const verifySignature = mergedOptions.verify_signature !== false;

  let payload;
  try {
    payload = jwsVerify(token, key, algorithms, { verify: verifySignature });
  } catch (err) {
    // python-jose re-raises every JWS problem as a JWTError carrying str(e).
    if (err instanceof JWSError) {
      throw new JWTError(err);
    }
    throw err;
  }

  // The at_hash validator needs the algorithm that actually signed the token.
  const headerAlgorithm = getUnverifiedHeader(token).get('alg');

  let claims;
  try {
    // pyJsonLoads decodes the bytes as UTF-8 itself, like payload.decode("utf-8").
    claims = pyJsonLoads(payload);
  } catch (err) {
    throw new JWTError(`Invalid payload string: ${err.message}`);
  }
  if (!(claims instanceof Map)) {
    throw new JWTError('Invalid payload string: must be a json object');
  }

  validateClaims(claims, {
    audience,
    issuer,
    subject,
    algorithm: headerAlgorithm,
    accessToken,
    options: mergedOptions,
  });

  return claims;
}

/**
 * Read a token's claims without verifying its signature.
 *
 * @param {string|Uint8Array} token the compact JWS
 * @returns {Map<string, *>} the decoded claims
 * @throws {JWTError} when the payload is not a JSON object
 */
export function getUnverifiedClaims(token) {
  return decode(token, '', { options: { verify_signature: false } });
}

/**
 * Read a token's header without verifying its signature.
 *
 * @param {string|Uint8Array} token the compact JWS
 * @returns {Map<string, *>} the decoded header
 */
export function getUnverifiedHeaders(token) {
  return getUnverifiedHeader(token);
}

/* ────────────────────────── claim validation ────────────────────────── */

/**
 * Run every enabled validator, in python-jose's order.
 *
 * @param {Map<string, *>} claims the decoded claims
 * @param {{audience: (string|null), issuer: *, subject: (string|null),
 *          algorithm: *, accessToken: (string|null), options: object}} context
 *   the caller's expectations plus the merged options (mutated, as in Python,
 *   when a `require_*` flag forces a `verify_*` flag on)
 */
function validateClaims(claims, context) {
  const { audience, issuer, subject, algorithm, accessToken, options } = context;
  const leeway = typeof options.leeway === 'number' ? options.leeway : 0;

  // require_<claim> makes the claim mandatory and switches its verifier on.
  for (const name of Object.keys(options)) {
    if (!name.startsWith(REQUIRE_PREFIX) || !options[name]) {
      continue;
    }
    const claimName = name.slice(REQUIRE_PREFIX.length);
    if (!claims.has(claimName)) {
      throw new JWTError(`missing required key "${claimName}" among claims`);
    }
    options[`verify_${claimName}`] = true;
  }

  if (!(audience === null || audience === undefined || typeof audience === 'string')) {
    throw new JWTError('audience must be a string or None');
  }

  if (options.verify_iat) {
    validateIat(claims);
  }
  if (options.verify_nbf) {
    validateNbf(claims, leeway);
  }
  if (options.verify_exp) {
    validateExp(claims, leeway);
  }
  if (options.verify_aud) {
    validateAud(claims, audience);
  }
  if (options.verify_iss) {
    validateIss(claims, issuer);
  }
  if (options.verify_sub) {
    validateSub(claims, subject);
  }
  if (options.verify_jti) {
    validateJti(claims);
  }
  if (options.verify_at_hash) {
    validateAtHash(claims, accessToken, algorithm);
  }
}

/**
 * `iat` must be convertible to an integer (this is the check the original
 * script switches on and off with --verify_iat).
 *
 * @param {Map<string, *>} claims the decoded claims
 * @throws {JWTClaimsError} when `iat` is not an integer
 */
function validateIat(claims) {
  if (!claims.has('iat')) {
    return; // 缺失的声明不算错误，除非设置了 require_iat
  }
  claimAsInteger(claims.get('iat'), 'Issued At claim (iat) must be an integer.');
}

/**
 * `nbf` must be an integer and must not be in the future (beyond the leeway).
 *
 * @param {Map<string, *>} claims the decoded claims
 * @param {number} leeway seconds of clock skew to tolerate
 * @throws {JWTClaimsError} when `nbf` is malformed or still in the future
 */
function validateNbf(claims, leeway) {
  if (!claims.has('nbf')) {
    return;
  }
  const notBefore = claimAsInteger(claims.get('nbf'), 'Not Before claim (nbf) must be an integer.');

  if (notBefore > nowEpochSeconds() + leeway) {
    throw new JWTClaimsError('The token is not yet valid (nbf)');
  }
}

/**
 * `exp` must be an integer and must not be in the past (beyond the leeway).
 *
 * @param {Map<string, *>} claims the decoded claims
 * @param {number} leeway seconds of clock skew to tolerate
 * @throws {JWTClaimsError} when `exp` is malformed
 * @throws {ExpiredSignatureError} when `exp` has passed
 */
function validateExp(claims, leeway) {
  if (!claims.has('exp')) {
    return;
  }
  const expiry = claimAsInteger(claims.get('exp'), 'Expiration Time claim (exp) must be an integer.');

  if (expiry < nowEpochSeconds() - leeway) {
    throw new ExpiredSignatureError('Signature has expired.');
  }
}

/**
 * `aud` must be a string or a list of strings, and must contain the audience
 * the caller expects.
 *
 * @param {Map<string, *>} claims the decoded claims
 * @param {string|null} audience the expected audience
 * @throws {JWTClaimsError} on a malformed or non-matching audience
 */
function validateAud(claims, audience) {
  if (!claims.has('aud')) {
    return;
  }

  const raw = claims.get('aud');
  const audienceClaims = typeof raw === 'string' ? [raw] : raw;

  if (!Array.isArray(audienceClaims)) {
    throw new JWTClaimsError('Invalid claim format in token');
  }
  if (audienceClaims.some((value) => typeof value !== 'string')) {
    throw new JWTClaimsError('Invalid claim format in token');
  }
  if (!audienceClaims.includes(audience)) {
    throw new JWTClaimsError('Invalid audience');
  }
}

/**
 * `iss` must match one of the issuers the caller accepts (only checked when the
 * caller supplied an expectation).
 *
 * @param {Map<string, *>} claims the decoded claims
 * @param {string|Array<string>|null} issuer accepted issuer(s)
 * @throws {JWTClaimsError} when the issuer does not match
 */
function validateIss(claims, issuer) {
  if (issuer === null || issuer === undefined) {
    return;
  }
  const accepted = typeof issuer === 'string' ? [issuer] : Array.from(issuer);

  if (!accepted.includes(claims.get('iss'))) {
    throw new JWTClaimsError('Invalid issuer');
  }
}

/**
 * `sub` must be a string, and must match the caller's expectation when given.
 *
 * @param {Map<string, *>} claims the decoded claims
 * @param {string|null} subject the expected subject
 * @throws {JWTClaimsError} when `sub` is not a string or does not match
 */
function validateSub(claims, subject) {
  if (!claims.has('sub')) {
    return;
  }
  if (typeof claims.get('sub') !== 'string') {
    throw new JWTClaimsError('Subject must be a string.');
  }
  if (subject !== null && subject !== undefined && claims.get('sub') !== subject) {
    throw new JWTClaimsError('Invalid subject');
  }
}

/**
 * `jti` must be a string.
 *
 * @param {Map<string, *>} claims the decoded claims
 * @throws {JWTClaimsError} when `jti` is not a string
 */
function validateJti(claims) {
  if (!claims.has('jti')) {
    return;
  }
  if (typeof claims.get('jti') !== 'string') {
    throw new JWTClaimsError('JWT ID must be a string.');
  }
}

/**
 * `at_hash` must match the hash of the access token the caller passed in.
 *
 * @param {Map<string, *>} claims the decoded claims
 * @param {string|null} accessToken the access token to hash
 * @param {*} algorithm the algorithm taken from the token header
 * @throws {JWTClaimsError} when the access token is missing or does not match
 */
function validateAtHash(claims, accessToken, algorithm) {
  if (!claims.has('at_hash')) {
    return;
  }
  if (!accessToken) {
    throw new JWTClaimsError('No access_token provided to compare against at_hash claim.');
  }

  let expected;
  try {
    expected = calculateAtHash(accessToken, algorithm);
  } catch (err) {
    throw new JWTClaimsError('Unable to calculate at_hash to verify against token claims.');
  }

  if (claims.get('at_hash') !== expected) {
    throw new JWTClaimsError('at_hash claim does not match access_token.');
  }
}

/* ─────────────────────────────── helpers ─────────────────────────────── */

/**
 * OpenID Connect `at_hash`: base64url of the left half of the access token's
 * hash (the hash paired with the signing algorithm — SHA-256 for HS256).
 *
 * @param {string} accessToken the access token to hash
 * @param {*} algorithm the signing algorithm
 * @returns {string} the `at_hash` value
 * @throws {Error} when the algorithm has no known hash
 */
function calculateAtHash(accessToken, algorithm) {
  if (algorithm !== HS256) {
    throw new Error(`No hash algorithm known for ${String(algorithm)}`);
  }

  const digest = sha256(utf8Encode(String(accessToken)));
  const half = Math.floor(digest.length / 2);
  return base64UrlEncode(digest.subarray(0, half));
}

/**
 * Coerce a claim to an integer the way python-jose's validators do with
 * `int(claims[...])`, turning any failure into the caller's JWTClaimsError.
 *
 * (python-jose only catches ValueError, so a list-valued claim escapes as a
 * TypeError there; normalising it to JWTClaimsError keeps the documented
 * contract "must be an integer" true for every input shape.)
 *
 * @param {*} value the raw claim value
 * @param {string} message the python-jose error wording for this claim
 * @returns {number} the integral value
 * @throws {JWTClaimsError} when the value is not convertible
 */
function claimAsInteger(value, message) {
  try {
    return pyInt(unwrapNumber(value));
  } catch (err) {
    throw new JWTClaimsError(message);
  }
}

/**
 * Unwrap the float marker the JSON parser uses for literals like "1.0" so the
 * value reaching pyInt() is a primitive it understands.
 *
 * @param {*} value a parsed JSON value
 * @returns {*} the same value, or the number inside a float marker
 */
function unwrapNumber(value) {
  if (value instanceof PyFloat) {
    return value.value;
  }
  if (value !== null && typeof value === 'object' && value.__pyFloat === true) {
    return Number(value.value);
  }
  return value;
}

/**
 * Copy the caller's claims into a `Map`, so encoding can add `at_hash` or
 * rewrite a time claim without mutating the caller's own container.
 *
 * @param {Map<string, *>|object} claims the claims mapping
 * @returns {Map<string, *>} a mutable copy in declaration order
 * @throws {JWTError} when `claims` is not a mapping
 */
function toClaimsMap(claims) {
  if (claims instanceof Map) {
    return new Map(claims);
  }
  if (claims !== null && typeof claims === 'object' && !Array.isArray(claims)) {
    return new Map(Object.entries(claims));
  }
  throw new JWTError('Expecting a mapping object, as JWT only supports JSON objects as payloads.');
}

/**
 * Overlay the caller's options on top of {@link DEFAULT_OPTIONS}.
 *
 * @param {Map<string, *>|object|null} overrides the caller's options
 * @returns {object} a fresh, mutable merged options object
 */
function mergeOptions(overrides) {
  const merged = { ...DEFAULT_OPTIONS };

  if (overrides === null || overrides === undefined) {
    return merged;
  }

  const entries = overrides instanceof Map ? overrides.entries() : Object.entries(overrides);
  for (const [name, value] of entries) {
    merged[name] = value;
  }
  return merged;
}

/**
 * index.mjs — the public surface of this pure-JavaScript JOSE port.
 *
 * A barrel with no side effects: importing it only wires up re-exports, it never
 * touches the process, the clock or any I/O.
 *
 *     import { jwt, ArgumentParser, pyRepr } from './lib/index.mjs';
 *
 *     const token = jwt.encode(claims, 'secret');
 *     const decoded = jwt.decode(token, 'secret', { algorithms: ['HS256'] });
 *     console.log(pyRepr(decoded));
 *
 * 公共入口：集中导出 jwt / jws / 异常类 / pyRepr / ArgumentParser。
 */

/** python-jose's `jose.jwt`: encode(), decode() and the decode option defaults. */
export * as jwt from './jwt.mjs';

/** python-jose's `jose.jws`: compact JWS sign(), verify() and the peek helpers. */
export * as jws from './jws.mjs';

/** python-jose's `jose.exceptions`, as a namespace for callers that prefer one. */
export * as errors from './errors.mjs';

// The exception hierarchy, also exported by name so `instanceof` checks and
// `catch` blocks read the way they do in the Python original.
export {
  JOSEError,
  JWSError,
  JWSSignatureError,
  JWSAlgorithmError,
  JWTError,
  JWTClaimsError,
  ExpiredSignatureError,
  JWKError,
} from './errors.mjs';

/** Python `repr()` for the values `jwt.decode()` returns (dict/str/int/...). */
export { pyRepr, pyReprString } from './pyrepr.mjs';

/** The `argparse.ArgumentParser` stand-in used by the command line entry point. */
export { ArgumentParser } from './argparse.mjs';

/**
 * jws_jwt_crosscheck.mjs — scratch verification for /output/lib/jws.mjs and
 * /output/lib/jwt.mjs. Lives outside /output on purpose.
 *
 * Usage: node /workspace/verify/jws_jwt_crosscheck.mjs <token> [<token> ...]
 * Every token must have been produced by the reference executable with the
 * secret "secret".
 */

import { jwt, jws, pyRepr, JWSSignatureError, JWTClaimsError, JWSError } from '/output/lib/index.mjs';
import { utf8Decode } from '/output/lib/bytes.mjs';
import { pyJsonDumpsCompact } from '/output/lib/pyjson.mjs';

const SECRET = 'secret';
let failures = 0;

function check(label, condition, detail = '') {
  const status = condition ? 'ok  ' : 'FAIL';
  if (!condition) failures += 1;
  console.log(`${status} ${label}${detail ? ` — ${detail}` : ''}`);
}

const tokens = process.argv.slice(2);
if (tokens.length === 0) {
  console.log('no tokens given');
  process.exit(1);
}

for (const token of tokens) {
  console.log(`\n=== ${token}`);

  // 1. the real cross-check: our HMAC must accept the reference signature
  let payloadBytes = null;
  try {
    payloadBytes = jws.verify(token, SECRET, ['HS256']);
    check('jws.verify accepts reference token', true);
  } catch (err) {
    check('jws.verify accepts reference token', false, `${err.name}: ${err.message}`);
  }

  if (payloadBytes) {
    console.log(`     payload json = ${utf8Decode(payloadBytes)}`);
  }

  // 2. header must be exactly the reference header
  const header = jws.getUnverifiedHeader(token);
  check(
    'header bytes',
    pyJsonDumpsCompact(header) === '{"alg":"HS256","typ":"JWT"}',
    pyJsonDumpsCompact(header)
  );

  // 3. decode with verify_iat both ways, and print the repr line
  for (const verifyIat of [true, false]) {
    const decoded = jwt.decode(token, SECRET, {
      algorithms: ['HS256'],
      options: { verify_iat: verifyIat },
    });
    console.log(`     verify_iat=${verifyIat} -> ${pyRepr(decoded)}`);
    check(`decode ok (verify_iat=${verifyIat})`, decoded instanceof Map && decoded.has('iat'));
    check(
      `claim order preserved (verify_iat=${verifyIat})`,
      [...decoded.keys()].join(',') === 'info,iat',
      [...decoded.keys()].join(',')
    );
  }

  // 4. re-signing the decoded claims must reproduce the reference token
  const decoded = jwt.decode(token, SECRET, { algorithms: ['HS256'] });
  const resigned = jwt.encode(decoded, SECRET);
  check('re-sign reproduces the reference token', resigned === token, resigned);

  // 5. tampering must be rejected
  const parts = token.split('.');
  const flipped = `${parts[0]}.${parts[1]}.${parts[2].slice(0, -1)}${parts[2].slice(-1) === 'A' ? 'B' : 'A'}`;
  let rejected = false;
  try {
    jws.verify(flipped, SECRET, ['HS256']);
  } catch (err) {
    rejected = err instanceof JWSSignatureError && err.message === 'Signature verification failed.';
  }
  check('tampered signature rejected', rejected);

  // 6. wrong key must be rejected, right key in a candidate list accepted
  let wrongKeyRejected = false;
  try {
    jws.verify(token, 'not-the-secret', ['HS256']);
  } catch (err) {
    wrongKeyRejected = err instanceof JWSSignatureError;
  }
  check('wrong key rejected', wrongKeyRejected);
  check('candidate key list accepted', (() => {
    try {
      jws.verify(token, ['nope', SECRET], ['HS256']);
      return true;
    } catch {
      return false;
    }
  })());

  // 7. algorithm allow-list
  let notAllowed = '';
  try {
    jws.verify(token, SECRET, ['HS512']);
  } catch (err) {
    notAllowed = `${err.name}: ${err.message}`;
  }
  check('disallowed alg', notAllowed === 'JWSError: The specified alg value is not allowed', notAllowed);

  // 8. verify=false skips the signature check
  check('verify:false skips signature', (() => {
    try {
      jws.verify(flipped, 'wrong', ['HS256'], { verify: false });
      return true;
    } catch {
      return false;
    }
  })());
}

/* ── structural / error-path checks that need no reference token ───────── */
console.log('\n=== structural');

function errorOf(fn) {
  try {
    fn();
    return 'no error';
  } catch (err) {
    return `${err.name}: ${err.message}`;
  }
}

check('own round trip', (() => {
  const claims = new Map([['info', 'ünïcødé 😀'], ['iat', 1786341257]]);
  const token = jwt.encode(claims, SECRET);
  const back = jwt.decode(token, SECRET, { algorithms: ['HS256'] });
  return pyRepr(back) === pyRepr(claims);
})());

check('known-answer token', (() => {
  // Built by hand from the ground-truth example (iat 1786341257).
  const claims = new Map([['info', 'iat_data_5'], ['iat', 1786341257]]);
  const token = jwt.encode(claims, SECRET);
  return token.startsWith(
    'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpbmZvIjoiaWF0X2RhdGFfNSIsImlhdCI6MTc4NjM0MTI1N30.'
  );
})());

check('one segment', errorOf(() => jws.verify('abc', SECRET, ['HS256'])) === 'JWSError: Not enough segments');
check('two segments', errorOf(() => jws.verify('a.b', SECRET, ['HS256'])) === 'JWSError: Not enough segments');
console.log(`     four segments -> ${errorOf(() => jws.verify('eyJhbGciOiJIUzI1NiJ9.a.b.c', SECRET, ['HS256']))}`);
console.log(`     bad header json -> ${errorOf(() => jws.verify('YWJj.YWJj.YWJj', SECRET, ['HS256']))}`);

check('missing alg', (() => {
  // header {"typ":"JWT"} has no alg
  const token = `${'eyJ0eXAiOiJKV1QifQ'}.eyJhIjoxfQ.AAAA`;
  return errorOf(() => jws.verify(token, SECRET, null)) ===
    'JWSError: No algorithm was specified in the JWS header.';
})());

check('unsupported alg in sign', errorOf(() => jws.sign(new Map(), SECRET, { algorithm: 'RS256' })) ===
  'JWSAlgorithmError: Algorithm not supported.');

check('extra headers are sorted', (() => {
  const token = jws.sign(new Map([['a', 1]]), SECRET, { headers: { kid: '1' } });
  return pyJsonDumpsCompact(jws.getUnverifiedHeader(token)) === '{"alg":"HS256","kid":"1","typ":"JWT"}';
})());

check('pem-looking secret refused', (() => {
  const message = errorOf(() => jws.sign(new Map(), '-----BEGIN PUBLIC KEY-----\nabc\n'));
  return message.startsWith('JWKError: The specified key is an asymmetric key');
})());

check('oct jwk key works', (() => {
  const token = jws.sign(new Map([['a', 1]]), SECRET);
  // base64url("secret") = c2VjcmV0
  jws.verify(token, { kty: 'oct', k: 'c2VjcmV0' }, ['HS256']);
  return true;
})());

/* jwt claim validators */
function tokenWith(claims) {
  return jwt.encode(new Map(Object.entries(claims)), SECRET);
}

check('verify_iat rejects a non-integer iat', (() => {
  const token = tokenWith({ info: 'x', iat: 'not-a-number' });
  const message = errorOf(() => jwt.decode(token, SECRET, { algorithms: ['HS256'] }));
  return message === 'JWTClaimsError: Issued At claim (iat) must be an integer.';
})());

check('verify_iat=false skips the iat check', (() => {
  const token = tokenWith({ info: 'x', iat: 'not-a-number' });
  const decoded = jwt.decode(token, SECRET, { algorithms: ['HS256'], options: { verify_iat: false } });
  return decoded.get('iat') === 'not-a-number';
})());

check('float iat is accepted (int(1.0) works in Python)', (() => {
  const token = tokenWith({ info: 'x', iat: 1786341257.5 });
  const decoded = jwt.decode(token, SECRET, { algorithms: ['HS256'] });
  return pyRepr(decoded.get('iat')) === '1786341257.5';
})());

check('expired exp', (() => {
  const token = tokenWith({ exp: 1 });
  return errorOf(() => jwt.decode(token, SECRET, { algorithms: ['HS256'] })) ===
    'ExpiredSignatureError: Signature has expired.';
})());

check('exp honoured with huge leeway', (() => {
  const token = tokenWith({ exp: 1 });
  jwt.decode(token, SECRET, { algorithms: ['HS256'], options: { leeway: 1e12 } });
  return true;
})());

check('verify_exp=false skips exp', (() => {
  const token = tokenWith({ exp: 1 });
  jwt.decode(token, SECRET, { algorithms: ['HS256'], options: { verify_exp: false } });
  return true;
})());

check('nbf in the future', (() => {
  const token = tokenWith({ nbf: 9999999999 });
  return errorOf(() => jwt.decode(token, SECRET, { algorithms: ['HS256'] })) ===
    'JWTClaimsError: The token is not yet valid (nbf)';
})());

check('aud mismatch', (() => {
  const token = tokenWith({ aud: 'them' });
  return errorOf(() => jwt.decode(token, SECRET, { algorithms: ['HS256'], audience: 'us' })) ===
    'JWTClaimsError: Invalid audience';
})());

check('aud match', (() => {
  const token = tokenWith({ aud: ['us', 'them'] });
  jwt.decode(token, SECRET, { algorithms: ['HS256'], audience: 'us' });
  return true;
})());

check('aud bad format', (() => {
  const token = tokenWith({ aud: 5 });
  return errorOf(() => jwt.decode(token, SECRET, { algorithms: ['HS256'], audience: 'us' })) ===
    'JWTClaimsError: Invalid claim format in token';
})());

check('non-string audience argument', (() => {
  const token = tokenWith({ aud: 'us' });
  return errorOf(() => jwt.decode(token, SECRET, { algorithms: ['HS256'], audience: 5 })) ===
    'JWTError: audience must be a string or None';
})());

check('iss mismatch', (() => {
  const token = tokenWith({ iss: 'a' });
  return errorOf(() => jwt.decode(token, SECRET, { algorithms: ['HS256'], issuer: 'b' })) ===
    'JWTClaimsError: Invalid issuer';
})());

check('sub must be a string', (() => {
  const token = tokenWith({ sub: 5 });
  return errorOf(() => jwt.decode(token, SECRET, { algorithms: ['HS256'] })) ===
    'JWTClaimsError: Subject must be a string.';
})());

check('jti must be a string', (() => {
  const token = tokenWith({ jti: 5 });
  return errorOf(() => jwt.decode(token, SECRET, { algorithms: ['HS256'] })) ===
    'JWTClaimsError: JWT ID must be a string.';
})());

check('require_exp on a token without exp', (() => {
  const token = tokenWith({ info: 'x' });
  return errorOf(() => jwt.decode(token, SECRET, { algorithms: ['HS256'], options: { require_exp: true } })) ===
    'JWTError: missing required key "exp" among claims';
})());

check('at_hash round trip', (() => {
  const accessToken = 'an-access-token';
  const token = jwt.encode(new Map([['info', 'x']]), SECRET, 'HS256', null, accessToken);
  const decoded = jwt.decode(token, SECRET, { algorithms: ['HS256'], accessToken });
  return typeof decoded.get('at_hash') === 'string' && decoded.get('at_hash').length === 22;
})());

check('at_hash without an access token', (() => {
  const token = jwt.encode(new Map([['info', 'x']]), SECRET, 'HS256', null, 'tok');
  return errorOf(() => jwt.decode(token, SECRET, { algorithms: ['HS256'] })) ===
    'JWTClaimsError: No access_token provided to compare against at_hash claim.';
})());

check('at_hash mismatch', (() => {
  const token = jwt.encode(new Map([['info', 'x']]), SECRET, 'HS256', null, 'tok');
  return errorOf(() => jwt.decode(token, SECRET, { algorithms: ['HS256'], accessToken: 'other' })) ===
    'JWTClaimsError: at_hash claim does not match access_token.';
})());

check('jwt.decode wraps signature failures as JWTError', (() => {
  const token = tokenWith({ info: 'x' });
  const message = errorOf(() => jwt.decode(token, 'wrong', { algorithms: ['HS256'] }));
  return message === 'JWTError: Signature verification failed.';
})());

check('DEFAULT_OPTIONS untouched by a merge', (() => {
  const token = tokenWith({ info: 'x' });
  jwt.decode(token, SECRET, { algorithms: ['HS256'], options: { verify_iat: false, require_iat: true } });
  return jwt.DEFAULT_OPTIONS.verify_iat === true && jwt.DEFAULT_OPTIONS.require_iat === false;
})());

check('plain-object options accepted', (() => {
  const token = tokenWith({ info: 'x' });
  jwt.decode(token, SECRET, { algorithms: ['HS256'], options: new Map([['verify_iat', true]]) });
  return true;
})());

check('JWSError export identity', JWSError.prototype instanceof Error);
check('JWTClaimsError export identity', JWTClaimsError.prototype instanceof Error);

console.log(`\n${failures === 0 ? 'ALL CHECKS PASSED' : `${failures} CHECK(S) FAILED`}`);
process.exit(failures === 0 ? 0 : 1);

